WITH flattened AS (SELECT id, service, host, log_ts, level, latency_ms, key, v FROM app_logs LATERAL VIEW EXPLODE(context) x AS key, v), valid AS (SELECT id, service, host, log_ts, level, latency_ms, key, v, DATEDIFF(CURRENT_DATE(), log_ts) AS days_since_log_ts FROM flattened WHERE log_ts >= TIMESTAMP '2025-06-01 07:00:00'), with_windows AS (SELECT id, service, host, level, key, v, MIN(days_since_log_ts) OVER (PARTITION BY key) AS key_min_days_since_log_ts, AVG(days_since_log_ts) OVER (PARTITION BY level, key ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS days_since_log_ts_avg_15m, LAST_VALUE(key, TRUE) OVER (PARTITION BY key ORDER BY latency_ms, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_key FROM valid WHERE latency_ms BETWEEN 1079 AND 1531), base AS (SELECT *, CASE WHEN host IN ('h1', 'h4') THEN 'Core' ELSE 'Other' END AS host_group, COALESCE(key, 'UNKNOWN') AS resolved_key FROM with_windows WHERE service = 'search'), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY host ORDER BY days_since_log_ts_avg_15m NULLS LAST, id, key) AS rank_in_group FROM base) x WHERE rank_in_group = 1) SELECT id, service, host, key, v, days_since_log_ts_avg_15m, last_known_key, host_group, rank_in_group, CASE WHEN host RLIKE '^(h2|h4)$' THEN 'CORE' WHEN host RLIKE '^(h1|h3)$' THEN 'GROUP_A' ELSE 'GROUP_B' END AS host_zone FROM ranked
